#[test]fn item_foreign_world_has_zero_recovery_budget_and_no_current_status(){tauri::async_runtime::block_on(async{
 let(mut c,mut s,dir,id,_)=claim_context();c.items=true;c.binding.scope.room_id=Some(uuid::Uuid::new_v4().to_string());let calls=Arc::new(std::sync::atomic::AtomicU64::new(0));let observed=calls.clone();c.owner.test_transport(move|_|{observed.fetch_add(1,std::sync::atomic::Ordering::AcqRel);Err("Foreign RPC".into())});s.cache.accept(0);s.page_schedule.next=Some(Instant::now()+Duration::from_secs(60));s.status.clear();
 for _ in 0..20{pump(&mut c,&mut s).await;}assert_eq!(calls.load(std::sync::atomic::Ordering::Acquire),0);assert!(s.recovery_schedule.next.is_none()&&s.operations.is_empty()&&s.effect.is_none()&&s.status.is_empty());assert!(action(&mut c,&mut s,Input::ItemPrepare{id,digest:"a".repeat(64),attempt:"b".repeat(32)}).await.is_err());assert!(s.prepares.is_empty()&&s.permissions.is_empty());drop(c);std::fs::remove_file(dir.join("originals.jsonl")).unwrap();std::fs::remove_dir(dir).unwrap();
});}

#[test]fn four_item_permissions_are_independent_and_offers_rotate_around_blocked_source(){tauri::async_runtime::block_on(async{
 let(mut c,mut s,dir,id,req)=claim_context();c.items=true;let mut requests=vec![(id,req)];for _ in 0..3{let id=uuid::Uuid::new_v4().to_string();let req=c.consumer.begin_item_with_id(crate::g3_items::Original{kind:"claim".into(),payload_json:json!({"itemId":uuid::Uuid::new_v4().to_string(),"expectedRevision":"2"}).to_string()},c.consumer.generation(),id.clone()).unwrap();requests.push((id,req));}
 let mut replies=BTreeMap::new();for(id,req)in &requests{let original=c.consumer.journal.pending().find(|p|p.record.original.operation_id==*id).unwrap().record.original;let digest=crate::g3_journal::operation_digest(&original).unwrap();let bytes=intent_reply(req,None,&c.binding.principal_id,&digest);let response:wire::Response=serde_json::from_slice(&bytes).unwrap();s.operations.insert(id.clone(),response.item_operation.clone().unwrap());replies.insert(id.clone(),response.item_operation.unwrap());}
 let replies_for_transport=replies.clone();c.owner.test_transport(move|bytes|{let q=protocol_g3::request(bytes).unwrap();let id=q.item_status.as_ref().unwrap().operation_id.as_ref().unwrap();Ok(serde_json::to_vec(&wire::Response{major:Some(1),revision:Some(protocol_g3::REVISION.into()),service_id:q.service_id,service_epoch:q.service_epoch,request_id:q.request_id,item_operation:Some(replies_for_transport[id].clone()),..Default::default()}).unwrap())});
 let mut offered=std::collections::BTreeSet::new();for _ in 0..8{offer_ready(&c,&mut s);offered.insert(s.effect.as_ref().unwrap()["id"].as_str().unwrap().to_owned());}assert_eq!(offered.len(),4,"An unprepared first source cannot monopolize offers");
 for(index,(id,_))in requests.iter().enumerate(){action(&mut c,&mut s,Input::ItemPrepare{id:id.clone(),digest:replies[id].payload_digest.clone().unwrap(),attempt:format!("{index:032x}")}).await.unwrap();offer_ready(&c,&mut s);assert_eq!(s.permissions.len(),index+1);let effects=s.effects();assert_eq!(effects.iter().filter(|v|v["stage"]=="permit").count(),index+1);assert!(effects.len()<=4);}
 for(index,(id,_))in requests.iter().enumerate(){let input=||Input::ItemPrepare{id:id.clone(),digest:replies[id].payload_digest.clone().unwrap(),attempt:format!("{index:032x}")};action(&mut c,&mut s,input()).await.unwrap();assert_eq!(s.permissions.len(),4);assert_eq!(c.consumer.journal.pending().find(|p|p.record.original.operation_id==*id).unwrap().record.phase,Phase::EffectIntent);}

// Retained diagnostic metadata belongs to the desktop/export, not game IPC.
for _ in 0..32{s.operations.insert(uuid::Uuid::new_v4().to_string(),replies.values().next().unwrap().clone());}
s.submissions=requests.iter().map(|(id,_)|json!({"id":id,"direction":"deposit","status":"accepted"})).collect();s.outgoing.clear();s.outgoing.push_back(Outgoing{id:uuid::Uuid::new_v4().to_string(),channel:"effect_item".into(),bytes:vec![b'x';CHUNK*2],offset:0});
let mut bank=super::super::State{items:s,status:"Gold transfer completed in this session.".into(),..Default::default()};bank.notices=(0..8).map(|i|json!({"id":i.to_string(),"text":format!("{} deposited 1000000 gold to the bank","a".repeat(64))})).collect();bank.effect=Some(json!({"id":uuid::Uuid::new_v4().to_string(),"digest":"a".repeat(64),"direction":"withdraw","amount":1000000,"stage":"permit","attempt":"b".repeat(32)}));
let bytes=bank.view();assert!(!bytes.is_empty()&&bytes.len()<=8192,"Full mailbox, four permits, notices and retained history must fit game IPC");let view:Value=serde_json::from_slice(&bytes).unwrap();assert_eq!(view["items"]["effects"].as_array().unwrap().len(),4);assert_eq!(view["items"]["chunk"]["data"].as_str().unwrap().len(),3072);assert!(view["items"]["diagnostics"]["operation_statuses"].is_null());s=std::mem::take(&mut bank.items);
 s.reattach();for(index,(id,_))in requests.iter().enumerate(){assert!(action(&mut c,&mut s,Input::ItemPrepare{id:id.clone(),digest:replies[id].payload_digest.clone().unwrap(),attempt:format!("{index:032x}")}).await.is_err());}assert!(s.permissions.is_empty());drop(c);std::fs::remove_file(dir.join("originals.jsonl")).unwrap();std::fs::remove_dir(dir).unwrap();
});}
